  const BUILTIN_WAVES = { sine: 1, square: 1, sawtooth: 1, triangle: 1 };
  const WAVE_FALLBACK = { pulse25: 'square', pulse12: 'square', warm: 'sawtooth', hollow: 'square', organ: 'sine' };

  function makeWaves(c) {
    const W = {};
    try {
      const mk = (n, fn) => {
        const re = new Float32Array(n + 1), im = new Float32Array(n + 1);
        for (let k = 1; k <= n; k++) { const v = fn(k); re[k] = v[0]; im[k] = v[1]; }
        return c.createPeriodicWave(re, im);
      };
      const pulse = (duty) => (k) => [sin(TAU * k * duty) / (Math.PI * k), (1 - cos(TAU * k * duty)) / (Math.PI * k)];
      W.pulse25 = mk(40, pulse(0.25));
      W.pulse12 = mk(48, pulse(0.125));
      W.warm = mk(32, (k) => [0, pow(k, -1.45) * (k % 2 ? 1 : -1)]);
      W.hollow = mk(24, (k) => [0, k % 2 ? pow(k, -1.1) : 0.04 / k]);
      const bars = { 1: 1, 2: 0.55, 3: 0.4, 4: 0.22, 6: 0.14, 8: 0.1 };
      W.organ = mk(16, (k) => [0, bars[k] || 0]);
    } catch (e) { }
    return W;
  }

  function synthNote(E, inst, dest, t, freqs, dur, vel, glideFrom) {
    const c = E.ctx;
    const A = inst.a || 0.005, D = inst.d || 0.3, S = inst.s === undefined ? 0.7 : inst.s, Rl = inst.r || 0.08;
    const n = freqs.length;
    const peak = max(0.0001, vel * (inst.gain || 0.3) / (n > 1 ? sqrt(n) : 1));
    const tOff = t + max(dur, A + 0.005);
    const env = c.createGain();
    const g = env.gain;
    g.setValueAtTime(0, t);
    g.linearRampToValueAtTime(peak, t + A);
    let stopAt;
    if (S <= 0) {
      g.setTargetAtTime(0, t + A, D / 5);
      stopAt = t + A + D * 1.25;
    } else {
      g.setTargetAtTime(peak * S, t + A, D / 4);
      g.setTargetAtTime(0, tOff, Rl / 5);
      stopAt = tOff + Rl * 1.3;
    }
    env.connect(dest);
    let input = env;
    if (inst.f) {
      const F = inst.f;
      const fl = c.createBiquadFilter();
      fl.type = F.type || 'lowpass';
      fl.Q.value = F.q || 0.8;
      const kt = F.kt ? pow(freqs[0] / 261.6, F.kt) : 1;
      const base = min(16000, F.cut * kt);
      const top = min(16000, base + (F.env || 0) * (0.35 + 0.65 * vel) * kt);
      const fdec = (F.dec || 0.2) / 3;
      if (F.a) {
        fl.frequency.setValueAtTime(base, t);
        fl.frequency.linearRampToValueAtTime(top, t + F.a);
        fl.frequency.setTargetAtTime(base, t + F.a, fdec);
      } else {
        fl.frequency.setValueAtTime(top, t);
        fl.frequency.setTargetAtTime(base, t + 0.002, fdec);
      }
      fl.connect(env);
      input = fl;
    }
    const oscs = [];
    const nyq = (c.sampleRate > 0 ? c.sampleRate : 44100) / 2;
    for (let k = 0; k < n; k++) {
      const f0 = freqs[k];
      for (let j = 0; j < inst.osc.length; j++) {
        const o = inst.osc[j];
        const f = f0 * (o.r || 1);
        if (!(f < nyq)) continue;
        const osc = c.createOscillator();
        const w = o.w || 'sine';
        if (E.waves && E.waves[w]) osc.setPeriodicWave(E.waves[w]);
        else osc.type = BUILTIN_WAVES[w] ? w : (WAVE_FALLBACK[w] || 'sawtooth');
        const g0 = glideFrom && inst.glide ? glideFrom * (o.r || 1) : 0, s0 = inst.slide ? f * pow(2, inst.slide / 12) : 0;
        if (glideFrom && inst.glide && g0 < nyq) {
          osc.frequency.setValueAtTime(g0, t);
          osc.frequency.exponentialRampToValueAtTime(f, t + inst.glide);
        } else if (inst.slide && !(glideFrom && inst.glide) && s0 < nyq) {
          osc.frequency.setValueAtTime(s0, t);
          osc.frequency.exponentialRampToValueAtTime(f, t + (inst.slideT || 0.05));
        } else osc.frequency.setValueAtTime(f, t);
        if (o.det) osc.detune.setValueAtTime(o.det, t);
        let node = osc;
        if (o.g !== undefined && o.g !== 1) { const og = c.createGain(); og.gain.value = o.g; osc.connect(og); node = og; }
        node.connect(input);
        if (inst.fm && j === 0 && f * inst.fm.r < nyq) {
          const mod = c.createOscillator();
          const mg = c.createGain();
          const mf = f * inst.fm.r;
          const depth = inst.fm.i * mf;
          mod.frequency.setValueAtTime(mf, t);
          mg.gain.setValueAtTime(depth, t);
          mg.gain.setTargetAtTime(depth * (inst.fm.sus || 0), t, (inst.fm.dec || 0.3) / 3);
          mod.connect(mg);
          mg.connect(osc.frequency);
          mod.start(t); mod.stop(stopAt + 0.02);
        }
        osc.start(t); osc.stop(stopAt + 0.02);
        oscs.push(osc);
      }
    }
    if (inst.vib && dur > (inst.vib.delay || 0) + 0.08) {
      const lfo = c.createOscillator();
      const lg = c.createGain();
      const dl = inst.vib.delay || 0;
      lfo.frequency.value = inst.vib.rate;
      lg.gain.setValueAtTime(0, t);
      lg.gain.setValueAtTime(0, t + dl);
      lg.gain.linearRampToValueAtTime(inst.vib.depth, t + dl + 0.3);
      lfo.connect(lg);
      for (const o of oscs) lg.connect(o.detune);
      lfo.start(t); lfo.stop(stopAt + 0.02);
    }
    E.stats.notes++;
  }

  const SCALES = {
    major: [0, 2, 4, 5, 7, 9, 11], minor: [0, 2, 3, 5, 7, 8, 10], dorian: [0, 2, 3, 5, 7, 9, 10],
    phrygian: [0, 1, 3, 5, 7, 8, 10], phrygianDom: [0, 1, 4, 5, 7, 8, 10], lydian: [0, 2, 4, 6, 7, 9, 11],
    mixolydian: [0, 2, 4, 5, 7, 9, 10], harmonicMinor: [0, 2, 3, 5, 7, 8, 11],
  };
  const ROMAN = { i: 0, ii: 1, iii: 2, iv: 3, v: 4, vi: 5, vii: 6 };
  const VEL = { X: 1, x: 0.78, o: 0.42 };
  const DRUM_MAP = { tom_lo: ['tom', 0.72], tom_mid: ['tom', 1], tom_hi: ['tom', 1.38], timp_lo: ['timp', 0.84], timp_hi: ['timp', 1.12] };

  function parseChord(tok) {
    const m = /^([b#]?)(VII|VI|V|IV|III|II|I|vii|vi|v|iv|iii|ii|i)(o|\+)?(M7|maj7|7|9|6|sus4|sus2|add9|5)?$/.exec(tok);
    if (!m) return null;
    const deg = ROMAN[m[2].toLowerCase()];
    const root = SCALES.major[deg] + (m[1] === 'b' ? -1 : m[1] === '#' ? 1 : 0);
    let tones = m[2] !== m[2].toLowerCase() ? [0, 4, 7] : [0, 3, 7];
    if (m[3] === 'o') tones = [0, 3, 6];
    if (m[3] === '+') tones = [0, 4, 8];
    switch (m[4]) {
      case 'M7': case 'maj7': tones.push(11); break;
      case '7': tones.push(m[3] === 'o' ? 9 : 10); break;
      case '9': tones.push(10, 14); break;
      case '6': tones.push(9); break;
      case 'add9': tones.push(14); break;
      case 'sus4': tones[1] = 5; break;
      case 'sus2': tones[1] = 2; break;
      case '5': tones = [0, 7, 12]; break;
      default: break;
    }
    return { root: ((root % 12) + 12) % 12, tones };
  }

  function compileTrack(id, T, errs) {
    errs = errs || [];
    const steps = T.steps || 16;
    const scaleArr = SCALES[T.scale || 'major'] || SCALES.major;
    const L = scaleArr.length;
    const key = T.key;
    const minor = scaleArr[2] === 3;
    const out = {
      id, bpm: T.bpm, steps, stepDur: 60 / T.bpm / (steps / 4), swing: T.swing || 0, gain: T.gain || 1, eq: T.eq || 0,
      parts: T.parts, delay: T.delay || null, bars: [], introBars: 0, loopBars: 0,
      key, scale: T.scale || 'major', minor, tonic: (((key + (minor ? 3 : 0)) % 12) + 12) % 12,
      layered: Object.keys(T.parts).some((pn) => !!T.parts[pn].lv),
    };
    const sections = {};
    for (const sname of Object.keys(T.sections)) {
      const S = Object.assign({}, T.base || {}, T.sections[sname]);
      const where = id + '.' + sname;
      const chordToks = String(S.chords || '').trim().split(/\s+/).filter(Boolean);
      const nb = chordToks.length;
      if (!nb) { errs.push(where + ': no chords'); continue; }
      const bars = [];
      let prev = null;
      for (let b = 0; b < nb; b++) {
        let chords;
        if (chordToks[b] === '%') chords = prev || [];
        else {
          chords = [];
          const pieces = chordToks[b].split(',');
          for (let i = 0; i < pieces.length; i++) {
            const ch = parseChord(pieces[i]);
            if (!ch) errs.push(where + ' bar ' + (b + 1) + ': bad chord "' + pieces[i] + '"');
            else chords.push({ at: round(i * steps / pieces.length), ch });
          }
        }
        prev = chords;
        const ev = [];
        for (let s = 0; s < steps; s++) ev.push([]);
        bars.push({ chords, events: ev });
      }
      const chordAt = (b, s) => { const cs = bars[b].chords; let c = cs[0] ? cs[0].ch : { root: 0, tones: [0, 4, 7] }; for (const x of cs) if (x.at <= s) c = x.ch; return c; };
      const vmul = S.vol === undefined ? 1 : S.vol;
      const tieLen = (str, i) => { let n = 1; while (i + n < str.length && str[i + n] === '-' && (i + n) % steps !== 0) n++; return n; };
      const charAt = (str, b, s) => str[(b * steps + s) % str.length];

      for (const pname of Object.keys(T.parts)) {
        const part = T.parts[pname];
        const pat = S[pname];
        if (!pat) continue;
        if (part.type === 'drums') {
          for (let b = 0; b < nb; b++) {
            const src = (S.fill && b === nb - 1 && pname === 'drums') ? Object.assign({}, pat, S.fill) : pat;
            for (const dn of Object.keys(src)) {
              const str = src[dn];
              if (!str) continue;
              if (str.length % steps) errs.push(where + ' drums.' + dn + ': length ' + str.length + ' not a multiple of ' + steps);
              const map = DRUM_MAP[dn] || [dn, 1];
              if (!DRUMS[map[0]]) { errs.push(where + ': unknown drum ' + dn); continue; }
              const mix = (part.mix && part.mix[dn] !== undefined) ? part.mix[dn] : 1;
              for (let s = 0; s < steps; s++) {
                const v = VEL[charAt(str, b, s)];
                if (v) bars[b].events[s].push({ p: pname, k: 'd', name: map[0], rate: map[1], vel: v * mix * vmul });
              }
            }
          }
        } else if (part.type === 'bass' || part.type === 'comp' || part.type === 'arp') {
          const str = String(pat);
          if (str.length % steps) errs.push(where + ' ' + pname + ': length ' + str.length + ' not a multiple of ' + steps);
          for (let b = 0; b < nb; b++) {
            for (let s = 0; s < steps; s++) {
              const i = (b * steps + s) % str.length;
              const c = str[i];
              if (c === '.' || c === '-' || c === undefined) continue;
              const ch = chordAt(b, s);
              const dur = tieLen(str, i);
              const lo = part.lo;
              const rootPc = (key + ch.root) % 12;
              const rootM = lo + ((rootPc - (lo % 12)) % 12 + 12) % 12;
              let midi = null, vel = 0.8;
              if (part.type === 'bass') {
                const t = ch.tones;
                const map = { R: 0, r: 0, 8: 12, 5: t[2], 3: t[1], 7: t[3] !== undefined ? t[3] : 12, L: t[2] - 12 };
                if (!(c in map)) { errs.push(where + ' ' + pname + ': bad bass symbol "' + c + '"'); continue; }
                midi = [rootM + map[c]];
                vel = c === 'r' ? 0.5 : c === 'R' ? 0.88 : 0.78;
              } else if (part.type === 'comp') {
                if (!VEL[c]) { errs.push(where + ' ' + pname + ': bad comp symbol "' + c + '"'); continue; }
                vel = VEL[c];
                if (part.power) midi = [rootM, rootM + 7, rootM + 12];
                else {
                  const center = part.center || (part.lo + part.hi) / 2;
                  midi = ch.tones.map((tt) => { let m = rootM + tt; while (m - center > 6) m -= 12; while (center - m > 6) m += 12; return m; }).sort((a, z) => a - z);
                }
              } else {
                const idx = c.charCodeAt(0) - 48;
                if (idx < 0 || idx > 9) { errs.push(where + ' ' + pname + ': bad arp symbol "' + c + '"'); continue; }
                const asc = ch.tones.map((tt) => rootM + tt).sort((a, z) => a - z);
                const n = asc.length;
                midi = [asc[idx % n] + 12 * floor(idx / n)];
                vel = 0.62 + ((s % 4) === 0 ? 0.25 : 0);
              }
              bars[b].events[s].push({ p: pname, k: 'n', midi, dur, vel: vel * vmul });
            }
          }
        } else if (part.type === 'melody') {
          const toks = String(pat).trim().split(/\s+/).filter(Boolean);
          const base = key + 12 * (part.oct || 0);
          let cur = 0;
          for (const tk of toks) {
            if (tk === '|') { if (cur % steps) errs.push(where + ' ' + pname + ': bar ends at step ' + cur + ' (not a multiple of ' + steps + ')'); continue; }
            const m = /^(r|-?\d+)([#b]?)([!?~]*)(?::(\d+))?$/.exec(tk);
            if (!m) { errs.push(where + ' ' + pname + ': bad token "' + tk + '"'); continue; }
            const len = m[4] ? parseInt(m[4], 10) : 2;
            if (m[1] !== 'r') {
              const di = parseInt(m[1], 10) - 1;
              const o = floor(di / L);
              const midi = base + scaleArr[di - o * L] + 12 * o + (m[2] === '#' ? 1 : m[2] === 'b' ? -1 : 0);
              const b = floor(cur / steps), s = cur % steps;
              if (b >= nb) { errs.push(where + ' ' + pname + ': melody longer than the section'); break; }
              const vel = m[3].indexOf('!') >= 0 ? 1 : m[3].indexOf('?') >= 0 ? 0.55 : 0.8;
              bars[b].events[s].push({ p: pname, k: 'n', midi: [midi], dur: len, vel: vel * vmul, glide: m[3].indexOf('~') >= 0 });
            }
            cur += len;
          }
          if (cur > nb * steps) errs.push(where + ' ' + pname + ': melody overflows the section (' + cur + ' > ' + nb * steps + ')');
        } else if (part.type !== 'dup') errs.push(where + ': part ' + pname + ' has unknown type');
      }
      for (const pname of Object.keys(T.parts)) {
        const part = T.parts[pname];
        if (part.type !== 'dup') continue;
        const src = T.parts[part.of];
        if (!src || src.type === 'drums' || src.type === 'dup') { errs.push(where + ': dup part ' + pname + ' needs a melodic part to double'); continue; }
        const tr = part.tr === undefined ? 12 : part.tr;
        for (const bar of bars) {
          for (const evs of bar.events) {
            const n = evs.length;
            for (let i = 0; i < n; i++) {
              const ev = evs[i];
              if (ev.p === part.of && ev.k === 'n') evs.push({ p: pname, k: 'n', midi: ev.midi.map((m) => m + tr), dur: ev.dur, vel: ev.vel * (part.vel || 1), glide: ev.glide });
            }
          }
        }
      }
      sections[sname] = bars;
    }
    const add = (list) => { let n = 0; for (const sn of list || []) { if (!sections[sn]) { errs.push(id + ': form references missing section ' + sn); continue; } for (const bar of sections[sn]) out.bars.push(bar); n += sections[sn].length; } return n; };
    out.introBars = add(T.intro);
    out.loopBars = add(T.form);
    if (!out.loopBars) errs.push(id + ': empty loop');
    out.loopSeconds = out.loopBars * steps * out.stepDur;
    return out;
  }

