  function scaled(v, scales, active, sk) {
    if (!sk) return v;
    const o = Object.assign({}, v);
    const mul = (keys, k) => { if (!(k > 0) || !isFinite(k)) return; for (const key of keys || []) if (typeof o[key] === 'number') o[key] *= k; };
    mul(scales.dmg, sk.dmg);
    mul((scales.pot || []).filter((key) => key !== 'arms'), sk.pot);
    if (active && typeof o.cd === 'number' && o.cd > 0) mul(['cd'], sk.cd);
    return o;
  }

  function gainPart(g, a, b, st) {
    const [key, fmt, label, many] = g;
    const x = a[key], y = b[key];
    if (typeof y !== 'number' || typeof x !== 'number') return '';
    switch (fmt) {
      case 'dmg': case 'pct': { const d = Math.round(y * 100) - Math.round(x * 100); return d > 0 ? '+' + d + '% ' + (label || 'damage') : ''; }
      case 'pct1': { const d = Math.round(y * 10000) - Math.round(x * 10000); return d > 0 ? '+' + (d / 100) + '% ' + label : ''; }
      case 'cd': { const d = Math.round((x - y) * 100) / 100; return d > 0 ? S(d) + ' faster' : ''; }
      case 'sec': { const d = Math.round((y - x) * 100) / 100; return d > 0 ? '+' + S(d) + ' ' + label : ''; }
      case 'n': { const d = Math.round(y) - Math.round(x); return d > 0 ? '+' + plural(d, label, many) : ''; }
      case 'num': { const d = Math.round(y) - Math.round(x); return d > 0 ? '+' + d + ' ' + label : ''; }
      case 'nth': return Math.round(y) < Math.round(x) ? 'every ' + ORD(y) + ' ' + W.stamp() : '';
      case 'def': { const k = biomeScale(st); const d = Math.round(y * k) - Math.round(x * k); return d > 0 ? '+' + N(d) + ' ' + W.skin() : ''; }
      case 'thorns': {
        const p = punchOf(st);
        if (p) { const d = Math.round(y * p) - Math.round(x * p); return d > 0 ? '+' + N(d) + ' damage back' : ''; }
        const d = Math.round(y * 100) - Math.round(x * 100);
        return d > 0 ? '+' + d + '% of a ' + W.stamp() + ' back' : '';
      }
      case 'revive': return y > 0 && !(x > 0) ? 'revive once' : '';
      case 'done': return Math.round(y * 100) > Math.round(x * 100) ? 'from ' + (100 - Math.round(y * 100)) + '% done' : '';
      default: return '';
    }
  }

  const KIT = { P, P1, S, N, ORD, EVERY, plural, W, nextArmLevel, punchOf, biomeScale, streakTime };
  const wordsOf = (id) => { const P = (KK.Data.glossary && KK.Data.glossary.actWords ? KK.Data.glossary.actWords() : KK.Theme && KK.Theme.pack); return (P && P.skills && P.skills[id]) || {}; };
