  const STYLE_COLORS = { strength: '#e8453c', speed: '#f5b81c', guard: '#3cb371', element: '#9b59f0' };
  const styleInfo = (s) => { const T = KK.Data.skillTree; return (T && T.styles && T.styles[s]) || null; };
  const styleName = (s) => { const st = styleInfo(s); const g = G(); return (st && st.name) || (g && g.styles && g.styles[s]) || s; };
