        let want = lv + extra;
        if (want > max) {
          for (let k = max; k < lv; k++) add('gear', oldPrice(k));
          add('gear', Math.min(extra, want - max) * oldPrice(lv));
          want = max;
        }
        let uid = typeof it.uid === 'string' && it.uid ? it.uid : KK.Util.uid('it');
        if (seen.has(uid)) uid = KK.Util.uid('it');
        seen.add(uid);
        const ni = { uid, slot, tpl: ID.TPL_BY_SLOT[slot].id, rarity: nr, level: want, locked: !!it.locked, isNew: !!it.isNew, spent: { gold: Math.floor(spent * rate) } };
        items.push(ni);
        if (eqUids.has(it.uid) && oldEq[slot] === it.uid && !equipped[slot]) equipped[slot] = uid;
