        unlocked: !!p && (tier < nB ? tier < p.biomes.unlocked || open : open),
        conquered,
        best: p ? (tier < nB ? num(p.biomes.best[bi]) : reached) : 0,
        reached,
        checkpoint: cp, checkpointOpen: open, giantWave: BW * (tier + 1), giantKills: kills,
        giantName: b && b.boss ? b.boss.giantName : '',
        recommended, power, ready: power >= recommended,
        difficulty: Progression.difficultyOf(power, recommended, conquered, reached),
