        KK.fx('shake', { amount: crit ? 6 : 4, dur: 0.12 });
        KK.fx('kick', { angle, amount: crit ? 5 : 3.5, zoom: crit ? 0.012 : 0.006, dur: crit ? 0.2 : 0.16 });
