      if (tier <= (h.comboTier | 0)) return 0;
      h.comboTier = tier;
      if (tier > (st.stats.bestComboTier | 0)) st.stats.bestComboTier = tier;
      const T = TIER_FX[tier - 1];
      KK.fx('callout', { x: h.x, y: h.y - 150, text: STREAK_TEXT(COMBO_TIERS[tier - 1]), sub: T.word, tier, color: T.color, follow: 'hero' });
      if (tier >= 3) KK.fx('ring', { x: h.x, y: h.y, r0: 24, r1: 120 + tier * 30, color: T.color, dur: 0.45, width: 5 + tier });
