    v.accessory = [m.raw.accessory, st && st.accessory, def.accessory].find((x) => typeof x === 'string' && x) || null;
    const size = Number([m.raw.size, st && st.size, def.size].find((x) => typeof x === 'number' && isFinite(x)));
    v.size = size >= 0.3 && size <= 1.2 ? size : 0.62;
