    cleave: {
      name: 'Back-to-Back', w: 1.2, cd: 4.5, max: (st, e) => e.r + st.hero.r + 150,
      start(st, e, P) {
        const t = T(e, 0.5);
        for (let k = 0; k < 2; k++) {
          P.at(k * 0.7, (s) => {
            e.facing = hAng(s, e) + (k ? 0.3 : -0.3);
            chargeUp(s, e, P, t);
            land(P, P.t + t, (s2) => {
              if (hDist(s2, e) <= e.r + s2.hero.r + 170) hitB(s2, e, 0.85, 'melee', t);
              setState(e, 'attack');
              KK.sfx('whoosh_heavy', { vol: 0.8 });
            });
          });
        }
        P.at(0.7 + t + 0.2, () => setState(e, 'recover'));
        P.dur = 0.7 + t + 0.45;
      },
    },
    charge: rushDef('Rush Request', { backoff: true, speed: 780, mult: 1.4, tell: 0.85, cd: 6 }),
    leap: {
      name: 'Skip-Level Leap', w: 1, cd: 6, big: true,
      start(st, e, P) {
        const h = st.hero;
        const a = hAng(st, e);
        const land0 = e.r + h.r + 8;
        const p = cp(h.x - Math.cos(a) * land0, h.y - Math.sin(a) * land0, e.r + 4);
        P.x0 = e.x; P.y0 = e.y; P.tx = p.x; P.ty = p.y;
        P.crouch = chargeUp(st, e, P, T(e, 0.7), { big: true });
        P.air = 0.7;
        land(P, P.crouch, () => { setState(e, 'charge'); KK.sfx('whoosh_heavy'); });
        P.at(P.crouch + P.air, (s) => {
          e.x = P.tx; e.y = P.ty; e.z = 0; e.vz = 0; P.landed = true;
          shockwave(s, e, e.r + 120, 1.3, '#ffd25a', P.crouch, true);
          setState(e, 'attack');
        });
        P.dur = P.crouch + P.air + 0.75;
        P.at(P.crouch + P.air + 0.3, () => setState(e, 'recover'));
      },
      tick(st, e, dt, P) {
        if (P.landed || P.t < P.crouch) return;
        const s = U.clamp((P.t - P.crouch) / P.air, 0, 1);
        e.x = U.lerp(P.x0, P.tx, s); e.y = U.lerp(P.y0, P.ty, s);
        e.z = 4 * 170 * s * (1 - s); e.vz = 0;
        e.facing = Math.atan2(P.ty - P.y0, P.tx - P.x0);
      },
    },
    summon: summonDef('Loop In', { n: 4, kinds: ['grunt', 'runner'], hpMult: 0.7, cd: 10 }),
