        if (arch.threat > budget + 1.2) { pick.w = 0; continue; }
        let n;
        if (k === 'swarm') { const gr = arch.group || [6, 10]; n = rng.int(gr[0], gr[1]) + Math.floor(Math.max(0, lw - 10) / 6); }
        else { const gr = GROUP[k] || [1, 2]; n = rng.int(gr[0], gr[1]) + (arch.threat <= 1.4 ? Math.floor(lw / 9) : 0); }
