      st.waveState = 'between';
      const bossWave = !!Waves.bossFor(w);
      const BR = Waves.BREATHER || BREATHER;
      st.betweenT = forced ? 0.01 : bossWave ? BR.boss : (lw % 5 === 0 ? BR.fifth : BR.wave);
