  function boomUpdate(st, p, dt) {
    const h = st.hero;
    p.spinA += dt * 22;
    if (p.phase === 'out') {
      const k = U.clamp(p.dist / p.range, 0, 1);
      p.speed = 720 * (0.28 + 0.72 * (1 - k * k));
      p.dist += p.speed * dt;
      const a = Math.atan2(p.vy, p.vx);
      p.vx = Math.cos(a) * p.speed; p.vy = Math.sin(a) * p.speed;
      if (p.dist >= p.range || !inArena(p.x, p.y, 10)) { p.phase = 'back'; p.backT = 0; p.hitIds.clear(); }
    } else {
      p.backT += dt;
      p.speed = Math.min(900, 220 + p.backT * 900);
      const a = U.angle(p.x, p.y, h.x, h.y - 6);
      p.vx = Math.cos(a) * p.speed; p.vy = Math.sin(a) * p.speed;
      if (U.dist2(p.x, p.y, h.x, h.y) < 30 * 30 || !h.alive) p.dead = true;
    }
  }


