  const SPOTS = [[-5.2, -4.6], [-5.2, 5.4], [5.2, -4.2], [5.2, 4.6], [1.6, -5.0], [1.6, 5.6], [-2.4, -3.6], [-2.4, 4.4], [3.6, -2.6], [3.6, 3.6]];
