      if (b && hyp(b.x - p.x, b.z - p.z) < R) { bot.seen = (bot.seen || 0) + 1 / 60; if (bot.seen >= react * 0.6 && p.stampCD <= 0) { inp.act = true; bot.seen = 0; } } else bot.seen = 0;
