      const home = TREES[HOMES[ev.rng.int(0, HOMES.length - 1)]];
      let best = null, bd = 18;
      for (const o of ev.litter) {
        if (o.dead || o.fly || o.taken || o.bin !== 'compost') continue;
        const d = hyp(o.x - home.x, o.z - home.z) - (o.kind === 'leaf' ? 0 : 3);
        if (d < bd) { bd = d; best = o; }
      }
      if (!best) { ev.squirrelAt[0] = ev.t + 3; return; }
      ev.squirrelAt.shift();
      Object.assign(S, { on: true, state: 'out', x: home.x + 0.8, z: home.z + 0.8, hx: home.x + 0.7, hz: home.z + 0.7, target: best.id, carry: '', t: 0, face: 0, walk: 0, hop: 0 });
      best.taken = 1;
