    h.state = 'leave'; h.t = 0; h.bubble = '✓'; h.hop = 1; A.say(h, thanks[(h.id + ev.stats.stamped) % thanks.length], 1.4);
    h.tx = h.x < PARK.cx ? R.x0 + 0.6 : R.x1 - 0.6; h.tz = h.z;
